const ee = require('@google/earthengine');
const privateKey = require('./.earthsense-436113-b294c1f5c2dc.json');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const year = 2023;
  const startDate = ee.Date.fromYMD(year, 1, 1);
  const endDate = ee.Date.fromYMD(year, 12, 31);

  // Define Quebec geometry by filtering a global administrative boundary dataset.
  const countries = ee.FeatureCollection("USDOS/LSIB_SIMPLE/2017");
  const quebec = countries.filter(ee.Filter.eq('wkb_geom_name', 'Quebec'));

  if (quebec.size().getInfo() === 0) {
    console.log("Error: Could not find Quebec geometry.");
    console.log("C1");
    return;
  }
  const geometry = quebec.first().geometry();

  // 2. Data Acquisition & Check
  // Use MODIS MCD64A1 Burned Area Product.
  const burnedAreaCol = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterDate(startDate, endDate)
    .filterBounds(geometry)
    .select('Burn_Date'); // Select the Burn_Date band

  const collectionSize = await burnedAreaCol.size().getInfo();
  console.log(`MCD64A1 images for ${year}: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No MCD64A1 images found for 2023 in Quebec. Trying fallback to a wider area and then filtering.");
    // Fallback: Sometimes filterBounds can be too restrictive if the image centroid is outside,
    // even if the image overlaps. Let's try without initial bounds filter and then clip.
    const fallbackCol = ee.ImageCollection('MODIS/061/MCD64A1')
      .filterDate(startDate, endDate)
      .select('Burn_Date');
    const fallbackSize = await fallbackCol.size().getInfo();
    console.log(`Fallback MCD64A1 images for ${year} (wider): ${fallbackSize}`);

    if (fallbackSize === 0) {
      console.log("C1"); // No images even in fallback
      return;
    }
    // If fallback worked, proceed with it and ensure geometry clipping
    burnedAreaCol = fallbackCol;
  }

  // 3. Processing
  // Mosaic the images to get a single image representing the maximum burn date for the year.
  // Pixels with Burn_Date > 0 indicate burned areas.
  const annualBurnedArea = burnedAreaCol.max();

  if (!annualBurnedArea) {
    console.log("C3"); // Mosaicing failed or resulted in null
    return;
  }

  // Create a binary image: 1 for burned pixels, 0 for unburned.
  // Burn_Date values range from 1 to 366 (day of year), 0 means no burn.
  const burnedMask = annualBurnedArea.gt(0);

  // Calculate the area of each pixel. MODIS MCD64A1 nominal resolution is 500m.
  const pixelAreaImage = ee.Image.pixelArea().mask(burnedMask);

  // Reduce the image to get the total burned area in square meters.
  // Use a sufficiently large scale (e.g., 1000m) to avoid memory errors,
  // the original resolution is 500m.
  const stats = await pixelAreaImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 500, // Use the native resolution for area calculation
    maxPixels: 1e9,
    crs: 'EPSG:4326', // Ensure consistent CRS
    crsTransform: [0.004491599903746618, 0, -180, 0, -0.004491599903746618, 90] // Match MODIS scale/projection if possible, or let GEE reproject.
  }).getInfo();

  const totalBurnedAreaSqM = stats['pixel_area'];

  if (totalBurnedAreaSqM === null || typeof totalBurnedAreaSqM === 'undefined') {
    console.log("Calculation of total burned area failed (null/undefined result).");
    console.log("C3");
    return;
  }

  // Check if no valid pixels remained after masking and reduction.
  // The 'pixel_area' band will be present if pixelAreaImage has data.
  const countPixels = await burnedMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 500,
    maxPixels: 1e9,
  }).getInfo();

  const validBurnedPixels = countPixels['Burn_Date'];

  if (validBurnedPixels === 0) {
    console.log("No valid burned pixels found after processing. (Area will be 0)");
    // This is a valid 0, meaning no fires were detected.
    // Proceed to answer B. No need for C2 as the area calculation is correctly 0.
  }

  // Convert square meters to hectares (1 hectare = 10,000 square meters)
  const totalBurnedAreaHa = totalBurnedAreaSqM / 10000;
  const thresholdHa = 0.8 * 1000000; // 0.8 million hectares

  console.log(`Total burned area in Quebec in 2023: ${totalBurnedAreaHa.toFixed(2)} hectares`);
  console.log(`Threshold: ${thresholdHa.toFixed(2)} hectares`);

  // 5. Validation & Final Answer
  if (totalBurnedAreaHa > thresholdHa) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
